<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;class StoreTrainingProgramRequest extends FormRequest{public function authorize(){return$this->user()?->can('capacitaciones.programa.crear')??false;}public function rules(){return['year'=>'required|integer|min:2020|max:2100','title'=>'required|string|max:255','general_objective'=>'required|string|max:4000','specific_objectives'=>'nullable|string|max:4000','scope'=>'required|string|max:4000','starts_at'=>'required|date','ends_at'=>'required|date|after_or_equal:starts_at','prepared_by'=>'nullable|exists:empleados,id'];}}
